1	:root {
2	  --bg: #0c0c0e;
3	  --fg: #efe9dd;
4	  --fg-muted: #b9b1a0;
5	  --accent: #c8a96a;
6	  --rule: rgba(232, 224, 207, 0.12);
7	  --serif: "Cormorant Garamond", "EB Garamond", Georgia, "Times New Roman", serif;
8	  --sans: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
9	  --header-h: 56px;
10	  --content-max: 60ch;
11	  --reveal-ease: cubic-bezier(0.22, 0.61, 0.36, 1);
12	}
13	
14	*,
15	*::before,
16	*::after {
17	  box-sizing: border-box;
18	}
19	
20	html,
21	body {
22	  margin: 0;
23	  padding: 0;
24	  background: var(--bg);
25	  color: var(--fg);
26	}
27	
28	body {
29	  font-family: var(--serif);
30	  font-size: 1.0625rem;
31	  line-height: 1.6;
32	  font-feature-settings: "liga", "kern";
33	  -webkit-font-smoothing: antialiased;
34	  text-rendering: optimizeLegibility;
35	  min-height: 100vh;
36	}
37	
38	a {
39	  color: var(--accent);
40	  text-decoration: none;
41	}
42	
43	a:hover,
44	a:focus-visible {
45	  text-decoration: underline;
46	}
47	
48	h1,
49	h2,
50	h3,
51	h4 {
52	  font-family: var(--serif);
53	  font-weight: 500;
54	  letter-spacing: 0.005em;
55	  margin: 0 0 0.5em;
56	}
57	
58	p {
59	  margin: 0 0 1em;
60	}
61	
62	/* ---------- Header & footer chrome ---------- */
63	
64	.site-header {
65	  position: sticky;
66	  top: 0;
67	  z-index: 10;
68	  display: flex;
69	  align-items: center;
70	  justify-content: space-between;
71	  gap: 1.5rem;
72	  height: var(--header-h);
73	  padding: 0 1.5rem;
74	  background: rgba(12, 12, 14, 0.92);
75	  backdrop-filter: saturate(140%) blur(8px);
76	  border-bottom: 1px solid var(--rule);
77	}
78	
79	.site-title {
80	  font-family: var(--serif);
81	  font-size: 1rem;
82	  font-weight: 500;
83	  letter-spacing: 0.02em;
84	  color: var(--fg);
85	}
86	
87	.site-title .accent {
88	  color: var(--accent);
89	}
90	
91	.site-nav {
92	  font-family: var(--sans);
93	}
94	
95	.dot-nav {
96	  list-style: none;
97	  display: flex;
98	  gap: 0.85rem;
99	  margin: 0;
100	  padding: 0;
101	}
102	
103	.dot-nav li {
104	  display: inline-flex;
105	}
106	
