108	  display: inline-block;
109	  width: 8px;
110	  height: 8px;
111	  border-radius: 50%;
112	  background: var(--fg-muted);
113	  opacity: 0.5;
114	  transition: opacity 120ms ease, background-color 120ms ease;
115	}
116	
117	.dot-nav a:hover .dot,
118	.dot-nav a:focus-visible .dot {
119	  background: var(--accent);
120	  opacity: 1;
121	}
122	
123	main {
124	  display: block;
125	}
126	
127	.site-footer {
128	  font-family: var(--sans);
129	  font-size: 0.8rem;
130	  color: var(--fg-muted);
131	  text-align: center;
132	  padding: 1.5rem;
133	  border-top: 1px solid var(--rule);
134	}
135	
136	.site-footer a {
137	  color: var(--fg-muted);
138	}
139	
140	.site-footer a:hover,
141	.site-footer a:focus-visible {
142	  color: var(--accent);
143	}
144	
145	/* ---------- Painter section ---------- */
146	
147	.painter-section {
148	  position: relative;
149	  border-bottom: 1px solid var(--rule);
150	}
151	
152	.painter-section:last-of-type {
153	  border-bottom: 0;
154	}
155	
156	/* Hero: full-viewport background image with overlay + ken-burns when visible */
157	
158	.painter-hero {
159	  position: relative;
160	  min-height: calc(100vh - var(--header-h));
161	  background-position: center;
162	  background-size: cover;
163	  background-repeat: no-repeat;
164	  display: flex;
165	  align-items: flex-end;
166	  overflow: hidden;
167	  /* baseline transform — ken-burns starts when .is-visible is added */
168	  transform: scale(1);
169	  transform-origin: center center;
170	  transition: transform 18s linear;
171	  will-change: transform;
172	}
173	
174	.painter-hero.is-visible {
175	  animation: ken-burns 22s ease-out forwards;
176	}
177	
178	@keyframes ken-burns {
179	  from {
180	    transform: scale(1);
181	    transform-origin: 50% 55%;
182	  }
183	  to {
184	    transform: scale(1.12);
185	    transform-origin: 50% 50%;
186	  }
187	}
188	
189	.painter-hero-overlay {
190	  position: absolute;
191	  inset: 0;
192	  background: linear-gradient(
193	    180deg,
194	    rgba(12, 12, 14, 0.55) 0%,
195	    rgba(12, 12, 14, 0.25) 35%,
196	    rgba(12, 12, 14, 0.85) 100%
197	  );
198	  pointer-events: none;
199	}
200	
201	.painter-hero-inner {
202	  position: relative;
203	  z-index: 1;
204	  width: 100%;
205	  max-width: 80rem;
206	  margin: 0 auto;
207	  padding: 4rem 1.5rem 3rem;
208	}
209	
210	.eyebrow {
211	  font-family: var(--sans);
212	  font-size: 0.75rem;
213	  letter-spacing: 0.18em;
214	  text-transform: uppercase;
215	  color: var(--accent);
216	  margin-bottom: 0.5rem;
217	}
218	
219	.painter-name {
220	  position: relative;
221	  display: inline-block;
222	  font-size: clamp(2.5rem, 6.5vw, 5.25rem);
223	  line-height: 1.05;
224	  margin: 0 0 0.35em;
225	  color: var(--fg);
226	  cursor: default;
227	}
228	
229	.painter-name .name-lv {
230	  display: inline-block;
231	  transition: opacity 320ms var(--reveal-ease);
232	}
233	
234	.painter-name .name-en {
235	  position: absolute;
236	  inset: 0;
237	  display: inline-flex;
238	  align-items: center;
239	  font-size: inherit;
240	  color: var(--accent);
241	  opacity: 0;
242	  transform: translateY(0.15em);
243	  transition: opacity 320ms var(--reveal-ease), transform 320ms var(--reveal-ease);
244	  pointer-events: none;
245	  letter-spacing: 0.005em;
246	}
247	
248	.painter-name:hover .name-lv,
249	.painter-name:focus-visible .name-lv {
250	  opacity: 0;
251	}
252	
253	.painter-name:hover .name-en,
254	.painter-name:focus-visible .name-en {
255	  opacity: 1;
256	  transform: translateY(0);
257	}
258	
259	.painter-years {
260	  font-family: var(--sans);
261	  font-size: 0.95rem;
262	  color: var(--fg-muted);
263	  letter-spacing: 0.04em;
264	  margin: 0;
265	}
266	
267	.painter-years .dash {
268	  margin: 0 0.25em;
269	}
270	
271	/* Body: bio prose, gallery strip, article link */
272	
273	.painter-body {
274	  max-width: 80rem;
275	  margin: 0 auto;
276	  padding: 4rem 1.5rem 5rem;
277	}
278	
279	.painter-bio {
280	  max-width: var(--content-max);
281	  margin: 0 0 2.5rem;
282	  font-size: 1.1875rem;
283	  line-height: 1.75;
284	  color: var(--fg);
285	}
286	
287	.gallery-strip {
288	  display: flex;
289	  gap: 1rem;
290	  overflow-x: auto;
291	  overflow-y: hidden;
292	  scroll-snap-type: x mandatory;
293	  -webkit-overflow-scrolling: touch;
294	  padding-bottom: 1rem;
295	  margin: 0 -1.5rem 2rem;
296	  padding-left: 1.5rem;
297	  padding-right: 1.5rem;
298	  scrollbar-width: thin;
