  font-feature-settings: "liga", "kern";
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover,
a:focus-visible {
  text-decoration: underline;
}

h1,
h2,
h3,
h4 {
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: 0.005em;
  margin: 0 0 0.5em;
}

p {
  margin: 0 0 1em;
}

/* ---------- Header & footer chrome ---------- */

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  height: var(--header-h);
  padding: 0 1.5rem;
  background: rgba(12, 12, 14, 0.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--rule);
}

.site-title {
  font-family: var(--serif);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--fg);
}

.site-title .accent {
  color: var(--accent);
}

.site-nav {
  font-family: var(--sans);
}

.dot-nav {
  list-style: none;
  display: flex;
  gap: 0.85rem;
  margin: 0;
  padding: 0;
}

.dot-nav li {
  display: inline-flex;
}

.dot-nav .dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg-muted);
  opacity: 0.5;
  transition: opacity 120ms ease, background-color 120ms ease;
}

.dot-nav a:hover .dot,
.dot-nav a:focus-visible .dot,
.dot-nav a.is-active .dot {
  background: var(--accent);
  opacity: 1;
}

main {
  display: block;
}

.site-footer {
  font-family: var(--sans);
  font-size: 0.8rem;
  color: var(--fg-muted);
  text-align: center;
  padding: 1.5rem;
  border-top: 1px solid var(--rule);
}

.site-footer a {
  color: var(--fg-muted);
}

.site-footer a:hover,
.site-footer a:focus-visible {
  color: var(--accent);
}

/* ---------- Painter section ---------- */

.painter-section {
  position: relative;
  border-bottom: 1px solid var(--rule);
  scroll-margin-top: var(--header-h);
}

.painter-section:last-of-type {
  border-bottom: 0;
}

/* Hero: full-viewport background image with overlay + ken-burns when visible */

.painter-hero {
  position: relative;
  min-height: calc(100vh - var(--header-h));
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  /* baseline transform — ken-burns starts when .is-visible is added */
  transform: scale(1);
  transform-origin: center center;
  transition: transform 18s linear;
  will-change: transform;
}

.painter-hero.is-visible {
  animation: ken-burns 22s ease-out forwards;
}

@keyframes ken-burns {
  from {
    transform: scale(1);
    transform-origin: 50% 55%;
  }
  to {
    transform: scale(1.12);
    transform-origin: 50% 50%;
  }
}

.painter-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(12, 12, 14, 0.55) 0%,
    rgba(12, 12, 14, 0.25) 35%,
    rgba(12, 12, 14, 0.85) 100%
  );
  pointer-events: none;
}

.painter-hero-inner {
  position: relative;
