  transform: translateY(0.15em);
  transition: opacity 320ms var(--reveal-ease), transform 320ms var(--reveal-ease);
  pointer-events: none;
  letter-spacing: 0.005em;
}

.painter-name:hover .name-lv,
.painter-name:focus-visible .name-lv {
  opacity: 0;
}

.painter-name:hover .name-en,
.painter-name:focus-visible .name-en {
  opacity: 1;
  transform: translateY(0);
}

.painter-years {
  font-family: var(--sans);
  font-size: 0.95rem;
  color: var(--fg-muted);
  letter-spacing: 0.04em;
  margin: 0;
