158	  if (lightbox) {
159	    const imageEl = lightbox.querySelector<HTMLImageElement>(".lightbox-image")!;
160	    const captionEl = lightbox.querySelector<HTMLElement>(".lightbox-caption")!;
161	    const prevBtn = lightbox.querySelector<HTMLButtonElement>(".lightbox-prev")!;
162	    const nextBtn = lightbox.querySelector<HTMLButtonElement>(".lightbox-next")!;
163	    const closeBtn = lightbox.querySelector<HTMLButtonElement>(".lightbox-close")!;
164	
165	    let currentItems: LightboxItem[] = [];
166	    let currentIndex = 0;
167	    let lastTrigger: HTMLElement | null = null;
168	
169	    const render = () => {
170	      const item = currentItems[currentIndex];
171	      if (!item) return;
172	      imageEl.src = item.url;
173	      imageEl.alt = item.alt;
174	      captionEl.textContent = item.alt;
175	    };
176	
177	    const openLightbox = (trigger: HTMLElement) => {
178	      const strip = trigger.closest(".gallery-strip");
179	      if (!strip) return;
180	      const triggers = Array.from(
181	        strip.querySelectorAll<HTMLButtonElement>(".gallery-trigger"),
182	      );
183	      const items: LightboxItem[] = triggers.map((t) => {
184	        const img = t.querySelector("img") as HTMLImageElement;
185	        return { url: img.src, alt: img.alt };
186	      });
187	      const idx = triggers.indexOf(trigger as HTMLButtonElement);
188	      if (idx < 0 || items.length === 0) return;
189	      currentItems = items;
190	      currentIndex = idx;
191	      lastTrigger = trigger;
192	      render();
193	      lightbox.classList.add("is-open");
194	      lightbox.setAttribute("aria-hidden", "false");
195	      document.body.classList.add("lightbox-open");
196	      closeBtn.focus();
197	    };
198	
199	    const closeLightbox = () => {
200	      lightbox.classList.remove("is-open");
201	      lightbox.setAttribute("aria-hidden", "true");
202	      document.body.classList.remove("lightbox-open");
203	      imageEl.removeAttribute("src");
204	      captionEl.textContent = "";
205	      if (lastTrigger) {
206	        lastTrigger.focus();
207	        lastTrigger = null;
208	      }
209	      currentItems = [];
210	    };
211	
212	    const step = (delta: number) => {
213	      if (currentItems.length === 0) return;
214	      currentIndex = (currentIndex + delta + currentItems.length) % currentItems.length;
215	      render();
216	    };
217	
218	    document.querySelectorAll<HTMLButtonElement>(".gallery-trigger").forEach((btn) => {
219	      btn.addEventListener("click", () => openLightbox(btn));
220	    });
221	
222	    prevBtn.addEventListener("click", () => step(-1));
223	    nextBtn.addEventListener("click", () => step(1));
224	    closeBtn.addEventListener("click", closeLightbox);
225	
226	    lightbox.addEventListener("click", (e) => {
227	      if (e.target === lightbox) closeLightbox();
228	    });
229	
230	    document.addEventListener("keydown", (e) => {
231	      if (!lightbox.classList.contains("is-open")) return;
232	      if (e.key === "Escape") {
233	        e.preventDefault();
234	        closeLightbox();
235	      } else if (e.key === "ArrowRight") {
236	        e.preventDefault();
237	        step(1);
238	      } else if (e.key === "ArrowLeft") {
239	        e.preventDefault();
240	        step(-1);
241	      }
242	    });
243	  }
244	
245	  // ---------- Dot-nav scroll tracking ----------
246	  const dotLinks = Array.from(
247	    document.querySelectorAll<HTMLAnchorElement>(".dot-nav a[data-target]"),
248	  );
249	  const sections = Array.from(
250	    document.querySelectorAll<HTMLElement>(".painter-section"),
251	  );
252	
253	  if (dotLinks.length > 0 && sections.length > 0 && "IntersectionObserver" in window) {
254	    const setActive = (id: string) => {
255	      dotLinks.forEach((a) => {
256	        a.classList.toggle("is-active", a.dataset.target === id);
257	      });
258	    };
259	
260	    // Use a thin band just below the sticky header so only one section is active.
261	    const navIO = new IntersectionObserver(
262	      (entries) => {
263	        for (const entry of entries) {
264	          if (entry.isIntersecting && entry.target.id) {
265	            setActive(entry.target.id);
266	          }
267	        }
268	      },
269	      { rootMargin: "-56px 0px -70% 0px", threshold: 0 },
270	    );
271	
272	    sections.forEach((s) => navIO.observe(s));
273	    // Default the first dot to active until the observer fires.
274	    if (sections[0]?.id) setActive(sections[0].id);
275	  }
276	</script>
