:root {
  --bg: #0c0c0e;
  --fg: #efe9dd;
  --fg-muted: #b9b1a0;
  --accent: #c8a96a;
  --rule: rgba(232, 224, 207, 0.12);
  --serif: "Cormorant Garamond", "EB Garamond", Georgia, "Times New Roman", serif;
  --sans: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --header-h: 56px;
  --content-max: 60ch;
  --reveal-ease: cubic-bezier(0.22, 0.61, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--fg);
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--serif);
  font-size: 1.0625rem;
  line-height: 1.6;
  font-feature-settings: "liga", "kern";
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover,
a:focus-visible {
  text-decoration: underline;
}

h1,
h2,
h3,
h4 {
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: 0.005em;
  margin: 0 0 0.5em;
}

p {
  margin: 0 0 1em;
}

/* ---------- Header & footer chrome ---------- */

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  height: var(--header-h);
  padding: 0 1.5rem;
  background: rgba(12, 12, 14, 0.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--rule);
}

.site-title {
  font-family: var(--serif);
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--fg);
}

.site-title .accent {
  color: var(--accent);
}

.site-nav {
  font-family: var(--sans);
}

.dot-nav {
  list-style: none;
  display: flex;
  gap: 0.85rem;
  margin: 0;
  padding: 0;
}

.dot-nav li {
  display: inline-flex;
}

.dot-nav .dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg-muted);
  opacity: 0.5;
  transition: opacity 120ms ease, background-color 120ms ease;
}

.dot-nav a:hover .dot,
.dot-nav a:focus-visible .dot,
.dot-nav a.is-active .dot {
  background: var(--accent);
  opacity: 1;
}

main {
  display: block;
}

.site-footer {
  font-family: var(--sans);
  font-size: 0.8rem;
  color: var(--fg-muted);
  text-align: center;
  padding: 1.5rem;
  border-top: 1px solid var(--rule);
}

.site-footer a {
  color: var(--fg-muted);
}

.site-footer a:hover,
.site-footer a:focus-visible {
  color: var(--accent);
}

/* ---------- Painter section ---------- */

.painter-section {
  position: relative;
  border-bottom: 1px solid var(--rule);
  scroll-margin-top: var(--header-h);
}

.painter-section:last-of-type {
  border-bottom: 0;
}

/* Hero: full-viewport background image with overlay + ken-burns when visible */

.painter-hero {
  position: relative;
  min-height: calc(100vh - var(--header-h));
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  /* baseline transform — ken-burns starts when .is-visible is added */
  transform: scale(1);
  transform-origin: center center;
  transition: transform 18s linear;
  will-change: transform;
}

.painter-hero.is-visible {
  animation: ken-burns 22s ease-out forwards;
}

@keyframes ken-burns {
  from {
    transform: scale(1);
    transform-origin: 50% 55%;
  }
  to {
    transform: scale(1.12);
    transform-origin: 50% 50%;
  }
}

.painter-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(12, 12, 14, 0.55) 0%,
    rgba(12, 12, 14, 0.25) 35%,
    rgba(12, 12, 14, 0.85) 100%
  );
  pointer-events: none;
}

.painter-hero-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 80rem;
  margin: 0 auto;
  padding: 4rem 1.5rem 3rem;
}

.eyebrow {
  font-family: var(--sans);
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.painter-name {
  position: relative;
  display: inline-block;
  font-size: clamp(2.5rem, 6.5vw, 5.25rem);
  line-height: 1.05;
  margin: 0 0 0.35em;
  color: var(--fg);
  cursor: default;
}

.painter-name .name-lv {
  display: inline-block;
  transition: opacity 320ms var(--reveal-ease);
}

.painter-name .name-en {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  font-size: inherit;
  color: var(--accent);
  opacity: 0;
  transform: translateY(0.15em);
  transition: opacity 320ms var(--reveal-ease), transform 320ms var(--reveal-ease);
  pointer-events: none;
  letter-spacing: 0.005em;
}

.painter-name:hover .name-lv,
.painter-name:focus-visible .name-lv {
  opacity: 0;
}

.painter-name:hover .name-en,
.painter-name:focus-visible .name-en {
  opacity: 1;
  transform: translateY(0);
}

.painter-years {
  font-family: var(--sans);
  font-size: 0.95rem;
  color: var(--fg-muted);
  letter-spacing: 0.04em;
  margin: 0;
}

.painter-years .dash {
  margin: 0 0.25em;
}

/* Body: bio prose, gallery strip, article link */

.painter-body {
  max-width: 80rem;
  margin: 0 auto;
  padding: 4rem 1.5rem 5rem;
}

.painter-bio {
  max-width: var(--content-max);
  margin: 0 0 2.5rem;
  font-size: 1.1875rem;
  line-height: 1.75;
  color: var(--fg);
}

.gallery-strip {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 1rem;
  margin: 0 -1.5rem 2rem;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  scrollbar-width: thin;
  scrollbar-color: var(--accent) transparent;
}

.gallery-strip::-webkit-scrollbar {
  height: 6px;
}

.gallery-strip::-webkit-scrollbar-thumb {
  background: var(--accent);
  border-radius: 3px;
}

.gallery-item {
  flex: 0 0 auto;
  width: clamp(220px, 28vw, 360px);
  margin: 0;
  scroll-snap-align: start;
  border: 1px solid var(--rule);
  background: rgba(255, 255, 255, 0.02);
}

.gallery-trigger {
  display: block;
  width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: zoom-in;
}

.gallery-trigger:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.gallery-item img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transition: opacity 200ms ease;
}

.gallery-trigger:hover img,
.gallery-trigger:focus-visible img {
  opacity: 0.85;
}

.painter-link-row {
  margin: 0;
}

.painter-link {
  font-family: var(--sans);
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  color: var(--accent);
  border-bottom: 1px solid transparent;
  transition: border-color 160ms ease, transform 160ms ease;
}

.painter-link:hover,
.painter-link:focus-visible {
  border-bottom-color: var(--accent);
  text-decoration: none;
}

/* ---------- Reveal animation ---------- */

.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 700ms var(--reveal-ease), transform 700ms var(--reveal-ease);
  will-change: opacity, transform;
}

.reveal.is-visible {
  opacity: 1;
  transform: none;
}

/* The hero needs its own animation as well as reveal — keep both compatible. */
.painter-hero.reveal {
  transform: translateY(24px) scale(1);
}

.painter-hero.reveal.is-visible {
  /* the ken-burns @keyframes drives transform from here */
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal,
  .reveal.is-visible {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .painter-hero,
  .painter-hero.is-visible {
    animation: none;
    transform: none;
  }
}

/* ---------- Lightbox ---------- */

.lightbox {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(8, 8, 10, 0.94);
  opacity: 0;
  pointer-events: none;
  transition: opacity 180ms ease;
}

.lightbox.is-open {
  opacity: 1;
  pointer-events: auto;
}

.lightbox-figure {
  position: relative;
  margin: 0;
  max-width: 92vw;
  max-height: 88vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lightbox-image {
  display: block;
  max-width: 92vw;
  max-height: 78vh;
  width: auto;
  height: auto;
  object-fit: contain;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  background: #000;
}

.lightbox-caption {
  font-family: var(--sans);
  font-size: 0.85rem;
  color: var(--fg-muted);
  text-align: center;
  margin: 0.75rem auto 0;
  max-width: 60ch;
  letter-spacing: 0.02em;
}

.lightbox-button {
  position: absolute;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--rule);
  background: rgba(12, 12, 14, 0.7);
  color: var(--fg);
  font-family: var(--sans);
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
  transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease;
}

.lightbox-button:hover,
.lightbox-button:focus-visible {
  background: rgba(200, 169, 106, 0.15);
  color: var(--accent);
  border-color: var(--accent);
  outline: none;
}

.lightbox-prev {
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
}

.lightbox-next {
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
}

.lightbox-close {
  top: 1rem;
  right: 1rem;
  font-size: 1.1rem;
}

@media (max-width: 600px) {
  .lightbox-prev {
    left: 0.5rem;
  }
  .lightbox-next {
    right: 0.5rem;
  }
}

body.lightbox-open {
  overflow: hidden;
}

